package org.apache.commons.math.stat.inference;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.ChiSquaredDistribution;
import org.apache.commons.math.distribution.ChiSquaredDistributionImpl;
import org.apache.commons.math.distribution.DistributionFactory;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ChiSquareTestImpl#chiSquare.
 */
public class ChiSquareTestImpl_chiSquare_TriageGen2Test {

    private ChiSquareTestImpl chiSquareTestImpl;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        chiSquareTestImpl = new ChiSquareTestImpl();
    }

    @Test
    public void testChiSquare_Success() {
        double[] expected = {10.0, 20.0, 30.0};
        long[] observed = {12L, 18L, 30L};

        // Calculation:
        // ((12-10)^2 / 10) + ((18-20)^2 / 20) + ((30-30)^2 / 30)
        // (4 / 10) + (4 / 20) + 0 = 0.4 + 0.2 = 0.6
        double expectedResult = 0.6;
        double actualResult = chiSquareTestImpl.chiSquare(expected, observed);

        assertEquals(expectedResult, actualResult, DELTA);
    }

    @Test
    public void testChiSquare_ExpectedLengthTooSmall() {
        double[] expected = {10.0};
        long[] observed = {10L};

        try {
            chiSquareTestImpl.chiSquare(expected, observed);
            org.junit.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("observed, expected array lengths incorrect", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_MismatchedLengths() {
        double[] expected = {10.0, 20.0};
        long[] observed = {10L, 20L, 30L};

        try {
            chiSquareTestImpl.chiSquare(expected, observed);
            org.junit.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("observed, expected array lengths incorrect", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ExpectedContainsNonPositive() {
        // Testing isPositive(expected) requirement
        double[] expected = {10.0, 0.0, 30.0};
        long[] observed = {10L, 10L, 10L};

        try {
            chiSquareTestImpl.chiSquare(expected, observed);
            org.junit.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("observed counts must be non-negative and expected counts must be postive", e.getMessage());
        }

        double[] expectedNegative = {10.0, -1.0, 30.0};
        long[] observedValid = {10L, 10L, 10L};
        try {
            chiSquareTestImpl.chiSquare(expectedNegative, observedValid);
            org.junit.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("observed counts must be non-negative and expected counts must be postive", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ObservedContainsNegative() {
        // Testing isNonNegative(observed) requirement
        double[] expected = {10.0, 20.0};
        long[] observed = {10L, -1L};

        try {
            chiSquareTestImpl.chiSquare(expected, observed);
            org.junit.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("observed counts must be non-negative and expected counts must be postive", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ZeroDeviation() {
        double[] expected = {10.0, 20.0};
        long[] observed = {10L, 20L};

        double actualResult = chiSquareTestImpl.chiSquare(expected, observed);
        assertEquals(0.0, actualResult, DELTA);
    }
}
